               @onchange="e => UpdateField(Personal with { Phone = (string?)e.Value ?? "" })" />
        @if (Errors.ContainsKey("Phone"))
        {
            <div class="invalid-feedback">@Errors["Phone"]</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input type="text" class="form-control @(Errors.ContainsKey("Address") ? "is-invalid" : "")"
               value="@Personal.Address"
               @onchange="e => UpdateField(Personal with { Address = (string?)e.Value ?? "" })" />
        @if (Errors.ContainsKey("Address"))
        {
            <div class="invalid-feedback">@Errors["Address"]</div>
        }
    </div>
</div>

<div class="d-flex justify-content-end mt-4">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            <span>Validating…</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public EventCallback<PersonalInfo> OnPersonalChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private Dictionary<string, string> Errors { get; set; } = new();
    private bool IsValidating { get; set; }

    private async Task UpdateField(PersonalInfo updated)
    {
        await OnPersonalChanged.InvokeAsync(updated);
    }

    private async Task HandleNext()
    {
        Errors.Clear();

        if (string.IsNullOrWhiteSpace(Personal.FullName))
            Errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Personal.Email))
            Errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Personal.Phone))
            Errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Personal.Address))
            Errors["Address"] = "Address is required.";

        if (Errors.Count > 0) return;

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Personal.Email);
            IsValidating = false;

            if (!isValid)
            {
                Errors["Email"] = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}
