+    private async Task UpdateField(PersonalInfo updated)
+    {
+        await OnPersonalChanged.InvokeAsync(updated);
+    }
+
+    private async Task HandleNext()
+    {
+        Errors.Clear();
+
+        if (string.IsNullOrWhiteSpace(Personal.FullName))
+            Errors["FullName"] = "Full name is required.";
+        if (string.IsNullOrWhiteSpace(Personal.Email))
+            Errors["Email"] = "Email is required.";
+        if (string.IsNullOrWhiteSpace(Personal.Phone))
+            Errors["Phone"] = "Phone is required.";
+        if (string.IsNullOrWhiteSpace(Personal.Address))
+            Errors["Address"] = "Address is required.";
+
+        if (Errors.Count > 0) return;
+
+        if (ValidateEmail is not null)
+        {
+            IsValidating = true;
+            StateHasChanged();
+
+            var isValid = await ValidateEmail(Personal.Email);
+            IsValidating = false;
+
+            if (!isValid)
+            {
+                Errors["Email"] = "Please enter a valid email address.";
+                return;
+            }
+        }
+
+        await OnNext.InvokeAsync();
+    }
+}
+

