@page "/apply"
@using sv_45d80078b4a94a77a637e78a5affd110.Components.JobApplication
@using sv_45d80078b4a94a77a637e78a5affd110.Models
@inject IApplicationService AppService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep" OnStepSelected="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Personal="@_personal"
                              OnPersonalChanged="p => _personal = p"
                              ValidateEmail="AppService.ValidateEmailAsync"
                              OnNext="() => GoToStep(_currentStep + 1)" />
            break;

        case 1:
            <WorkHistoryStep Entries="@_workEntries"
                             OnEntriesChanged="e => _workEntries = e"
                             OnBack="() => GoToStep(_currentStep - 1)"
                             OnNext="() => GoToStep(_currentStep + 1)" />
            break;

        case 2:
            <ReferencesStep References="@_references"
                            OnReferencesChanged="r => _references = r"
                            OnBack="() => GoToStep(_currentStep - 1)"
                            OnNext="() => GoToStep(_currentStep + 1)" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             OnCoverLetterChanged="c => _coverLetter = c"
                             OnBack="() => GoToStep(_currentStep - 1)"
                             OnNext="() => GoToStep(_currentStep + 1)" />
            break;

        case 4:
            <ReviewStep Personal="@_personal"
                        WorkEntries="@_workEntries"
                        References="@_references"
                        CoverLetter="@_coverLetter"
                        OnBack="() => GoToStep(_currentStep - 1)"
                        OnEditSection="GoToStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private PersonalInfo _personal = new("", "", "", "");
    private List<WorkEntry> _workEntries = [new("", "", DateTime.Today, null, "")];
    private List<Reference> _references = [new("", "", "", ""), new("", "", "", "")];
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        _currentStep = Math.Clamp(step, 0, 4);
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            _personal,
            new WorkHistory(_workEntries),
            _references,
            _coverLetter);

        return await AppService.SubmitApplicationAsync(application);
    }
}

